text(await tools.exec_command({cmd:"rg --files","max_output_tokens":4000}));
text(await tools.exec_command({cmd:"python3 - <<'PY'
import hashlib,json,pathlib
for r in json.loads(pathlib.Path('contract-manifest.json').read_text()):
 p=pathlib.Path(r['path'])
 try:
  b=p.read_bytes()
  actual=hashlib.sha256(b).hexdigest()
  print(json.dumps({'role':r['role'],'path':str(p),'expected':r['sha256'],'actual':actual,'status':'matches' if actual==r['sha256'] else 'DIGEST MISMATCH','bytes':len(b)},ensure_ascii=False))
 except Exception as e:
  print(json.dumps({'role':r['role'],'path':str(p),'status':'UNAVAILABLE','error':str(e)},ensure_ascii=False))
PY","max_output_tokens":4000}));
const results = await Promise.allSettled([
 tools.exec_command({cmd:"cat contracts/r01.md contracts/r02.md contracts/r03.md","max_output_tokens":24000}),
 tools.exec_command({cmd:"cat contracts/r04.md contracts/r05.md","max_output_tokens":20000}),
 tools.exec_command({cmd:"cat contracts/r06.md contracts/r07.md","max_output_tokens":20000}),
 tools.exec_command({cmd:"cat contracts/r08.md contracts/r09.md contracts/r10.md contracts/r11.md contracts/r12.md contracts/r13.md","max_output_tokens":26000})
]);results.forEach((v,i)=>text({batch:i,...v}));

